INSERT INTO `wp_posts` VALUES ('83','0','2026-10-21 03:26:35','2026-10-20 20:26:35','<p>Vui lòng xác nhận phương thức thanh toán với cửa hàng trước khi hoàn tất đơn hàng.</p>','Hướng dẫn thanh toán','','publish','closed','closed','','nem-info-6','','','2026-10-21 03:26:35','2026-10-20 20:26:35','','0','http://wordpress.local/CK_NHOMF_CMS/nem-info-6/','0','page','','0');
